INSERT INTO FactCashBalances (SK_CustomerID, SK_AccountID, SK_DateID, BatchID, Cash) SELECT CAST(DA.SK_CustomerID AS INT) AS SK_CustomerID, CAST(DA.SK_AccountID AS INT) AS SK_AccountID, CAST(DD.SK_DateID AS INT) AS SK_DateID, CAST(1 AS DECIMAL(5, 0)) AS BatchID, CAST(COALESCE(SUM(CT.CT_AMT), 0) AS DECIMAL(15, 2)) AS Cash FROM Source.CashTransaction AS CT, DimAccount AS DA, DimDate AS DD WHERE CT.CT_CA_ID = DA.AccountID AND CAST(CT_DTS AS DATE) BETWEEN DA.EffectiveDate AND DA.EndDate AND CAST(CT_DTS AS DATE) = DD.DateValue GROUP BY DA.SK_CustomerID, DA.SK_AccountID, DD.SK_DateID, CAST(CT_DTS AS DATE);
